import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './styles.css'; // Asegúrate de tener los estilos

function Opiniones() {
  const [comentario, setComentario] = useState('');
  const [rating, setRating] = useState(0);
  const [opinionesLista, setOpinionesLista] = useState([]);

  const handleEnviar = () => {
    if (comentario && rating > 0) {
      setOpinionesLista([...opinionesLista, { comentario, rating }]);
      setComentario('');
      setRating(0);
    }
  };

  return (
    <div>
      <header>
        <div className="logo-contenedor">
          <img src="Logotipo.jpg" alt="Logo Taller Robledo" className="logo" />
          <div className="texto-logo">
            <span className="slogan">FABRICACIÓN DE VOLCOS</span>
            <span className="nombre">TALLER ROBLEDO</span>
          </div>
        </div>
        <nav>
          <ul className="menu">
            <li><Link to="/">Inicio</Link></li>
            <li><Link to="/volcos">Volcos</Link></li>
            <li><Link to="/cotizacion">Cotización</Link></li>
            <li><Link to="/contacto">Contacto</Link></li>
            <li><Link to="/opiniones">Opiniones</Link></li>
            <li><Link to="/registro">Registro</Link></li>
          </ul>
        </nav>
      </header>

      <main>
        <h1>Califique Nuestro Servicio</h1>

        <div className="rating" id="rating">
          {[5,4,3,2,1].map((valor) => (
            <span
              key={valor}
              data-value={valor}
              onClick={() => setRating(valor)}
              style={{ cursor: 'pointer', color: valor <= rating ? '#ffc107' : '#e4e5e9', fontSize: '2rem' }}
            >
              ★
            </span>
          ))}
        </div>

        <textarea
          value={comentario}
          onChange={(e) => setComentario(e.target.value)}
          rows="4"
          placeholder="Escriba su opinión..."
        ></textarea>

        <button onClick={handleEnviar}>Enviar Opinión</button>

        <div id="opinionesLista">
          {opinionesLista.map((op, index) => (
            <div key={index} className="opinion-item">
              <p>⭐ {op.rating}</p>
              <p>{op.comentario}</p>
            </div>
          ))}
        </div>
      </main>

      <footer className="footer">
        <div className="footer-left">
          <p>Taller Robledo | 📞 314 880 5733</p>
        </div>
        <div className="footer-right">
          <p>&copy; 2025 Todos los derechos reservados</p>
        </div>
      </footer>
    </div>
  );
}

export default Opiniones;
